import { appendFileSync } from 'node:fs'
export const byId = (id: string) => 'android=new UiSelector().resourceId("'+id+'")'
export const byText = (text: string) => 'android=new UiSelector().text("'+text+'")'
export async function tap(driver, selector) { const e=driver.$(selector);await e.waitForDisplayed();await e.click() }
export async function open(driver,...items) {for(const item of items)await tap(driver,byText(item))}
export async function textEntries(driver, count) {
 await open(driver,'Views','Controls','1. Light Theme')
 const field=driver.$(byId('io.appium.android.apis:id/edit'));await field.waitForDisplayed()
 for(let i=0;i<count;i++) {const value='entry-'+i;await field.setValue(value);await driver.waitUntil(async()=>await field.getText()===value)}
}
